const MAX_CHARS = 100000;
const raw = $input.item.json.html || '';
let cleaned = raw
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<svg[\s\S]*?<\/svg>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/\s+/g, ' ')
  .trim();
if (cleaned.length > MAX_CHARS) {
  cleaned = cleaned.slice(0, MAX_CHARS);
}
return [{ json: { url: $input.item.json.url, cleanedHtml: cleaned } }];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "price": {
      "type": "string",
      "description": "The current selling price of the single main product on this page, digits only with its decimal separator, no currency symbol (e.g. 129.90). Use the discounted price when both a crossed-out and a current price are shown."
    },
    "currency": {
      "type": "string",
      "description": "Three-letter ISO currency code of the price (e.g. EUR, USD, GBP), inferred from the currency symbol or the page's markup."
    },
    "availability": {
      "type": "string",
      "description": "Stock status of the main product exactly as the page states it (e.g. In stock, Out of stock, Sold out, Pre-order, Backorder). Use the add-to-cart state when no explicit label exists."
    },
    "productTitle": {
      "type": "string",
      "description": "The product title as displayed on the page."
    },
    "sku": {
      "type": "string",
      "description": "Product SKU, MPN, or reference code if the page shows one, otherwise an empty string."
    }
  }
}

