// Compares this run's extracted values with the ones stored in the watchlist row.
// Batch size is 1, so .first() is the product currently in the loop.
const row = $('Loop Over Watchlist Items').first().json;
const extracted = $input.first().json.output || {};

// Parses "1.299,00 €", "$1,299.00", "129.90" -> 1299 / 1299 / 129.9
const toNumber = (value) => {
  if (value === null || value === undefined) return null;
  const cleaned = String(value).replace(/\s/g, '').replace(/[^0-9.,-]/g, '');
  if (!cleaned) return null;
  const lastComma = cleaned.lastIndexOf(',');
  const lastDot = cleaned.lastIndexOf('.');
  const normalized = lastComma > lastDot
    ? cleaned.replace(/\./g, '').replace(/,/g, '.')
    : cleaned.replace(/,/g, '');
  const parsed = parseFloat(normalized);
  return Number.isFinite(parsed) ? parsed : null;
};

// Normalises free-text stock wording (and the tokens written back to the sheet).
const toState = (value) => {
  const text = String(value === null || value === undefined ? '' : value).toLowerCase().replace(/_/g, ' ');
  if (!text.trim()) return 'unknown';
  if (/(out of stock|sold ?out|unavailable|no longer available|discontinued|rupture de stock|agotado)/.test(text)) return 'out_of_stock';
  if (/(pre ?order|coming soon)/.test(text)) return 'preorder';
  if (/back ?order/.test(text)) return 'backorder';
  if (/(in stock|instock|available|add to cart|buy now|en stock|disponible)/.test(text)) return 'in_stock';
  return 'unknown';
};

const productName = row.productName || extracted.productTitle || row.url;
const currency = extracted.currency || row.currency || '';

const newPrice = toNumber(extracted.price);
const oldPrice = toNumber(row.lastPrice);
const newState = toState(extracted.availability);
const oldState = toState(row.lastAvailability);

// Nothing recorded yet -> this run only writes the baseline, it never alerts.
const hasBaseline = oldPrice !== null || oldState !== 'unknown';

const changes = [];
let changeType = 'unchanged';

if (newState !== oldState && newState !== 'unknown' && oldState !== 'unknown') {
  if (newState === 'in_stock') {
    changeType = 'back_in_stock';
    changes.push('back in stock');
  } else if (newState === 'out_of_stock') {
    changeType = 'out_of_stock';
    changes.push('went out of stock');
  } else {
    changeType = 'availability_change';
    changes.push('availability ' + oldState + ' -> ' + newState);
  }
}

let priceDeltaPct = null;
if (newPrice !== null && oldPrice !== null && newPrice !== oldPrice) {
  if (oldPrice !== 0) {
    priceDeltaPct = Math.round(((newPrice - oldPrice) / oldPrice) * 1000) / 10;
  }
  const dropped = newPrice < oldPrice;
  if (changeType === 'unchanged') changeType = dropped ? 'price_drop' : 'price_rise';
  const pctText = priceDeltaPct === null ? '' : ' (' + (priceDeltaPct > 0 ? '+' : '') + priceDeltaPct + '%)';
  changes.push((dropped ? 'price dropped ' : 'price rose ') + oldPrice + ' -> ' + newPrice + (currency ? ' ' + currency : '') + pctText);
}

const changed = hasBaseline && changes.length > 0;
const icons = {
  price_drop: '📉',
  price_rise: '📈',
  back_in_stock: '✅',
  out_of_stock: '🚫',
  availability_change: 'ℹ️',
};

return [{
  json: {
    url: row.url,
    productName,
    productTitle: extracted.productTitle || '',
    sku: extracted.sku || row.sku || '',
    currency,
    price: extracted.price || '',
    priceValue: newPrice,
    availability: extracted.availability || '',
    availabilityState: newState,
    previousPrice: row.lastPrice === undefined || row.lastPrice === null ? '' : String(row.lastPrice),
    previousAvailability: row.lastAvailability === undefined || row.lastAvailability === null ? '' : String(row.lastAvailability),
    priceDeltaPct,
    changed,
    changeType: changed ? changeType : (hasBaseline ? 'unchanged' : 'baseline_recorded'),
    changeSummary: changed
      ? changes.join(' · ')
      : (hasBaseline ? 'no price or stock change' : 'baseline recorded on first check'),
    icon: changed ? (icons[changeType] || 'ℹ️') : '✅',
    // Values persisted back to the watchlist. When the extractor could not read a
    // price or a stock status, the previous value is kept so a bad parse never
    // wipes the reference point (and never fakes a change on the next run).
    sheetPrice: newPrice !== null ? String(newPrice) : (row.lastPrice === undefined || row.lastPrice === null ? '' : String(row.lastPrice)),
    sheetAvailability: newState !== 'unknown' ? newState : (row.lastAvailability === undefined || row.lastAvailability === null ? '' : String(row.lastAvailability)),
    checkedAt: new Date().toISOString(),
  },
}];
